use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let cs: Vec<char> = line.chars().collect()
        let n: int = cs.len() as int
        let mut fields: Vec<string> = []
        let mut cur = ""
        let mut inq = false
        let mut i: int = 0
        while i < n {
            let c = cs[i as usize]
            if inq {
                if c == '"' {
                    if i + 1 < n && cs[(i + 1) as usize] == '"' {
                        cur = cur + "\""
                        i += 1
                    } else {
                        inq = false
                    }
                } else {
                    cur = cur + c.to_string()
                }
            } else if c == '"' {
                inq = true
            } else if c == ',' {
                fields.push(cur)
                cur = ""
            } else if c != '\r' {
                cur = cur + c.to_string()
            }
            i += 1
        }
        fields.push(cur)
        let cnt: int = fields.len() as int
        let mut out = ""
        let mut first = true
        for f in fields {
            if !first {
                out = out + "|"
            }
            first = false
            out = out + "[" + f + "]"
        }
        println("${cnt}: ${out}")
    }
}

